arguments.command:
curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -d '{"query":"{ __type(name: \"Mutation\") { fields { name args { name type { name kind ofType { name kind } } } } } }"}' | python3 -c "
import json,sys
for f in json.load(sys.stdin)['data']['__type']['fields']:
    if f['name'] in ('cycleUpdate','issueUpdate'):
        print(f['name'])
        for a in f['args']:
            t=a['type']
            tn = t['name'] or (t.get('ofType') or {}).get('name') or t['kind']
            print('  ', a['name'], tn, t['kind'])
"

